update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle à Dijon et en Côte-d''Or","mecanisme":"Le bassin dijonnais fait cohabiter des lignes de conditionnement alimentaire, des salles propres pharmaceutiques et des centres d''usinage. Trois régimes d''hygiène et de traçabilité qui n''acceptent pas la même équipe ni les mêmes gammes. Nous ajustons l''intervenant au régime du site, depuis notre hub de techniciens de Dijon.","cta":"Demander une intervention à Dijon","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option pour les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels et agroalimentaires en France, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats passent l''entretien technique et comportemental, résultats transmis avant l''intervention"},{"valeur":"10","libelle":"hubs de techniciens en France, dont un à Dijon, plus notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid"}]},{"type":"probleme","punchline":"Une remplisseuse se met en défaut à 17h00, la veille d''un départ camion. Le produit est déjà dosé, le lot est engagé, et le planning de la semaine tient sur cette ligne.","puces":[{"accroche":"Le conditionnement alimentaire ne rattrape pas ses heures.","texte":"Un arrêt en fin de poste repousse tout le plan de charge, lot après lot."},{"accroche":"Les salles propres interdisent l''improvisation.","texte":"Tenue, outillage, traitement d''air, traçabilité : entrer sans le protocole coûte plus cher que d''attendre."},{"accroche":"Les pics viticoles et céréaliers tombent au même moment.","texte":"Fin d''été, début d''automne : les équipements doivent être prêts avant, pas dépannés pendant."},{"accroche":"L''usinage perd sa précision en silence.","texte":"Sans contrôle géométrique régulier, la dérive apparaît sur les pièces avant d''apparaître sur la machine."},{"accroche":"Un départ dans l''équipe, et la GMAO se vide de sens.","texte":"Les historiques deviennent illisibles pour celui qui reste."}]},{"type":"offre","lignes":[{"prestation":"**Intervenants formés aux régimes d''hygiène** : tenue, outillage dédié, protocole d''entrée en zone contrôlée.","benefice":"Votre responsable qualité n''arbitre plus entre la panne et la conformité."},{"prestation":"**Préventif calé sur le calendrier de production**, resserré avant les campagnes saisonnières.","benefice":"Les opérations lourdes tombent dans les creux, jamais sur un pic."},{"prestation":"**Utilités suivies au même titre que les lignes** : air comprimé, eau glacée, traitement d''air, réseaux de chaleur.","benefice":"Un défaut d''utilité arrête plusieurs ateliers à la fois, et il se prévient."},{"prestation":"**Contrôle géométrique et remise en état des machines d''usinage** : alignements, paliers, réducteurs, broches.","benefice":"La précision se pilote sur des relevés au lieu de se constater sur des rebuts."},{"prestation":"**Couverture multi-technique** : [mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/).","benefice":"Un seul interlocuteur pour une panne qui mélange les métiers."},{"prestation":"**Astreinte 24/24 et 7/7 en option**, mobilisée depuis notre hub de techniciens de Dijon.","benefice":"Une panne du samedi ne devient pas un lundi de production perdu."}],"prose":[{"texte":"Les lignes de fabrication et de conditionnement relèvent de notre pratique de la [maintenance en agroalimentaire](/secteurs/agroalimentaire/). Les entrepôts et plateformes de l''axe autoroutier relèvent de la [maintenance des équipements logistiques](/secteurs/logistique/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"équipement, symptôme, criticité, contraintes d''accès et régime du site."},{"titre":"Nous vous rappelons dans l''heure","texte":"qualification de la demande, du régime d''hygiène exigé et des pièces à prévoir."},{"titre":"Le devis précède l''intervention","texte":"périmètre, conditions, chiffrage écrit. Rien d''exceptionnel n''apparaît à la facture."},{"titre":"L''intervention respecte votre protocole","texte":"accueil sécurité, plan de prévention, consignation, diagnostic."},{"titre":"La cause racine passe après la remise en route","texte":"mesures, historique, conditions d''exploitation réelles."},{"titre":"Le compte rendu part dans votre GMAO","texte":"constat, actions, pièces, organes à surveiller."}]},{"type":"garanties","puces":[{"accroche":"Vous savez qui intervient avant qu''il n''arrive","texte":"10 % des candidats retenus après entretien technique et comportemental, résultats d''évaluation partagés."},{"accroche":"Aucun délai de route inventé","texte":"rappel dans l''heure aux horaires ouvrés, astreinte 24/24 et 7/7 en option. Le reste se dit avant d''engager, jamais après."},{"accroche":"Vos données restent chez vous","texte":"comptes rendus versés dans votre outil, historiques exploitables par votre équipe et par votre direction."}]},{"type":"cta","question":"Besoin de reprendre un préventif que le correctif a fini par manger ?","bouton":"Demander une intervention à Dijon","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Deux techniciens intégrés en 3x8 sur des lignes liquides et poudre","texte":"nutrition infantile, cadence continue, site de Steenvoorde","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"1 à 3 techniciens en renfort des équipes maintenance sur plusieurs sites de production, depuis octobre 2024","texte":"disponibilité machine jouée chaque semaine","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"},{"titre":"Un technicien intégré pendant l''arrêt estival pour tenir les équipements critiques","texte":"été 2025, équipe à moitié en congés","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"},{"titre":"Un électromécanicien habilité risque chimique RC1 mobilisé six mois sur un site de traitement des eaux industrielles","texte":"remise en état complète","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Un technicien polyvalent sur un parc machines hétérogène en forte cadence","texte":"papier et emballage, 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment sur place, à Dijon ?","reponse":"Oui : Dijon est l''un de nos dix hubs de techniciens en France, et nos techniciens basés à Dijon couvrent la Côte-d''Or au quotidien. Derrière ce hub, notre siège à Lyon et nos agences de Montréal, Dubaï et Madrid. La question utile porte ensuite sur le technicien qui franchit votre portail. Son niveau, ses habilitations, son outillage, et la trace qu''il laisse dans votre GMAO."},{"question":"Quelles communes couvrez-vous en Côte-d''Or ?","reponse":"Dijon et sa couronne, Chenôve, Talant, Quetigny, Longvic, Saint-Apollinaire, puis Beaune et la côte, le Val de Saône jusqu''à Chalon-sur-Saône. Au-delà, le réseau national prend le relais avec les mêmes méthodes et le même format de comptes rendus."},{"question":"Intervenez-vous en zone à atmosphère contrôlée ?","reponse":"Oui, sous votre protocole : tenue, outillage dédié, traçabilité des passages, coordination avec votre qualité. Les opérations qui imposent un arrêt se planifient avec votre production, pas contre elle."},{"question":"Pouvez-vous couvrir plusieurs sites d''un même groupe ?","reponse":"Oui, avec un contrat unique, un interlocuteur et des comptes rendus au même format partout en France. Une usine en Côte-d''Or et une autre ailleurs se pilotent dans le même cadre."},{"question":"Comment gérez-vous les pics de fin d''été ?","reponse":"Le plan préventif se resserre en amont sur les équipements critiques, et le renfort se dimensionne à l''avance. Pour un arrêt technique, la préparation se cadre de J-90 à J-30, avec restitution à la demi-journée."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"L''abonnement [Zéro arrêt](/offres/zero-arret/) est chiffré sur devis, engagement type 6 mois renouvelable. Préventif planifié, priorité en cas de panne, astreinte en option, périmètre écrit équipement par équipement après un diagnostic gratuit."}]},{"type":"ctaFinal","question":"Besoin d''un état des lieux chiffré de votre parc avant d''arbitrer le budget ?","bouton":"Demander une intervention à Dijon","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/maintenance-industrielle-dijon/';
